class Board {
    private Symbol[][] grid; // the actual N by N grid of cells
    private int size;        // the board's side length, e.g. 3 for classic tic-tac-toe

    Board(int size) {
        this.size = size;              // remember how big this board is
        grid = new Symbol[size][size]; // allocate the grid
        for (int r = 0; r < size; r++) {       // walk every row
            for (int c = 0; c < size; c++) {   // walk every column in that row
                grid[r][c] = Symbol.EMPTY;     // every cell starts empty
            }
        }
    }

    // Attempts to place a symbol at (row, col). Returns false if the move is illegal
    boolean placeMark(int row, int col, Symbol symbol) {
        if (row < 0 || row >= size || col < 0 || col >= size) {
            return false; // the requested cell is not even on the board
        }
        if (grid[row][col] != Symbol.EMPTY) {
            return false; // the cell is already taken, cannot overwrite it
        }
        grid[row][col] = symbol; // both checks passed, the move is legal
        return true;
    }

    Symbol getCell(int row, int col) {
        return grid[row][col]; // simple read access, used heavily by WinningStrategy
    }

    int getSize() {
        return size; // simple accessor
    }

    // True only once every single cell has a symbol on it
    boolean isFull() {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == Symbol.EMPTY) {
                    return false; // found at least one open cell, board is not full
                }
            }
        }
        return true; // scanned everything, nothing was empty
    }
}

