// Strategy pattern: each way of winning gets its own independent checker.
// TicTacToeGame just asks every strategy "did this exact move win?" after each move
interface WinningStrategy {
    boolean checkWin(Board board, int row, int col, Symbol symbol);
}

// Checks whether the ENTIRE row the last move was placed in is all one symbol
class RowWinStrategy implements WinningStrategy {
    @Override
    public boolean checkWin(Board board, int row, int col, Symbol symbol) {
        for (int c = 0; c < board.getSize(); c++) { // walk every column in this row
            if (board.getCell(row, c) != symbol) {
                return false; // found a cell that breaks the row, no win here
            }
        }
        return true; // every cell in the row matched, this row is a win
    }
}

// Checks whether the ENTIRE column the last move was placed in is all one symbol
class ColumnWinStrategy implements WinningStrategy {
    @Override
    public boolean checkWin(Board board, int row, int col, Symbol symbol) {
        for (int r = 0; r < board.getSize(); r++) { // walk every row in this column
            if (board.getCell(r, col) != symbol) {
                return false; // found a cell that breaks the column, no win here
            }
        }
        return true; // every cell in the column matched, this column is a win
    }
}

// Checks the main diagonal (top-left to bottom-right) and the anti-diagonal
// (top-right to bottom-left), but only the one(s) the last move actually sits on
class DiagonalWinStrategy implements WinningStrategy {
    @Override
    public boolean checkWin(Board board, int row, int col, Symbol symbol) {
        int size = board.getSize();
        boolean onMainDiagonal = (row == col);              // true if this cell is on the main diagonal
        boolean onAntiDiagonal = (row + col == size-1);      // true if this cell is on the anti-diagonal

        if (!onMainDiagonal && !onAntiDiagonal) {
            return false; // this move is not on either diagonal, cannot be a diagonal win
        }

        boolean mainWin = onMainDiagonal; // only bother checking if we are actually on it
        if (onMainDiagonal) {
            for (int i = 0; i < size; i++) {
                if (board.getCell(i, i) != symbol) {
                    mainWin = false; // this diagonal is broken somewhere
                    break;
                }
            }
        }

        boolean antiWin = onAntiDiagonal; // only bother checking if we are actually on it
        if (onAntiDiagonal) {
            for (int i = 0; i < size; i++) {
                if (board.getCell(i, size-1-i) != symbol) {
                    antiWin = false; // this diagonal is broken somewhere
                    break;
                }
            }
        }

        return mainWin || antiWin; // a win on EITHER diagonal counts
    }
}

