// Plain data holder: a player's name and symbol never change once created
class Player {
    private String name;    // this player's display name
    private Symbol symbol;  // this player's mark, X or O

    Player(String name, Symbol symbol) {
        this.name = name;     // store the given name
        this.symbol = symbol; // store the given symbol
    }

    String getName() {
        return name; // simple accessor
    }

    Symbol getSymbol() {
        return symbol; // simple accessor
    }
}

// Factory pattern: turns a plain text symbol into the correct Player,
// centralizing validation of what symbols are actually allowed
class PlayerFactory {
    static Player createPlayer(String name, String symbolText) {
        Symbol symbol;
        if (symbolText.equals("X")) {
            symbol = Symbol.X; // recognized as X
        } else if (symbolText.equals("O")) {
            symbol = Symbol.O; // recognized as O
        } else {
            throw new IllegalArgumentException("Unknown symbol: " + symbolText); // anything else is invalid
        }
        return new Player(name, symbol); // only reachable with a valid symbol
    }
}

// Observer pattern: anything that wants to react to game events implements this
interface GameListener {
    void onMoveMade(Player player, int row, int col);
    void onGameWon(Player player);
    void onGameDraw();
}

// One concrete listener: simply prints every event to the console
class ConsoleGameListener implements GameListener {
    @Override
    public void onMoveMade(Player player, int row, int col) {
        // report exactly who moved, their symbol, and where they placed it
        System.out.println(player.getName() + " placed " + player.getSymbol() + " at (" + row + "," + col + ")");
    }

    @Override
    public void onGameWon(Player player) {
        System.out.println(player.getName() + " wins!"); // announce the winner
    }

    @Override
    public void onGameDraw() {
        System.out.println("Game ended in a draw"); // announce a full board with no winner
    }
}

