import java.util.List;
import java.util.ArrayList;

// Orchestrates the whole game: whose turn it is, placing marks,
// checking every winning strategy, and detecting a draw
public class TicTacToeGame {
    private Board board;                              // the grid itself
    private List<Player> players;                      // both players in turn order
    private int currentPlayerIndex;                    // whose turn it is right now
    private List<WinningStrategy> winningStrategies;   // every way a win can be detected
    private List<GameListener> listeners = new ArrayList<>(); // everyone watching for events
    private boolean gameOver;                          // becomes true once a win or draw happens

    public TicTacToeGame(int boardSize, List<Player> players) {
        this.board = new Board(boardSize);              // create an empty board of the requested size
        this.players = players;                          // remember the players and their turn order
        this.currentPlayerIndex = 0;                     // the first player in the list goes first
        this.gameOver = false;                           // the game has not ended yet

        // register one strategy per way a player can win
        winningStrategies = new ArrayList<>();
        winningStrategies.add(new RowWinStrategy());
        winningStrategies.add(new ColumnWinStrategy());
        winningStrategies.add(new DiagonalWinStrategy());
    }

    public void addListener(GameListener listener) {
        listeners.add(listener); // register a new observer, does not replace existing ones
    }

    // Attempts one move for whichever player is currently up.
    // Returns true only if this move ended the game (win or draw)
    public boolean makeMove(int row, int col) {
        if (gameOver) {
            return false; // no moves are accepted once the game has already ended
        }

        Player currentPlayer = players.get(currentPlayerIndex); // whose turn is it

        if (!board.placeMark(row, col, currentPlayer.getSymbol())) {
            return false; // the requested cell was invalid or already occupied
        }

        // the move was legal, tell every listener it happened
        for (GameListener listener : listeners) {
            listener.onMoveMade(currentPlayer, row, col);
        }

        // ask every winning strategy whether THIS specific move just won the game
        for (WinningStrategy strategy : winningStrategies) {
            if (strategy.checkWin(board, row, col, currentPlayer.getSymbol())) {
                gameOver = true; // the game ends the instant any strategy reports a win
                for (GameListener listener : listeners) {
                    listener.onGameWon(currentPlayer);
                }
                return true; // signal to the caller that the game is over
            }
        }

        // no strategy reported a win, check whether the board is now completely full
        if (board.isFull()) {
            gameOver = true; // every cell is filled and nobody won: a draw
            for (GameListener listener : listeners) {
                listener.onGameDraw();
            }
            return true; // signal to the caller that the game is over
        }

        currentPlayerIndex = (currentPlayerIndex + 1) % players.size(); // pass the turn along
        return false; // game continues
    }
}

