// Owns the grid itself and the two simplest operations on it: place and inspect
class Board {
    private Symbol[][] grid;
    private int size;

    Board(int size) {
        this.size = size;
        grid = new Symbol[size][size];
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                grid[r][c] = Symbol.EMPTY; // every cell starts empty
            }
        }
    }

    boolean placeMark(int row, int col, Symbol symbol) {
        if (row < 0 || row >= size || col < 0 || col >= size) {
            return false; // outside the board entirely
        }
        if (grid[row][col] != Symbol.EMPTY) {
            return false; // cell already occupied
        }
        grid[row][col] = symbol;
        return true;
    }

    Symbol getCell(int row, int col) {
        return grid[row][col];
    }

    int getSize() {
        return size;
    }

    boolean isFull() {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == Symbol.EMPTY) return false;
            }
        }
        return true;
    }
}

// Strategy pattern: each way of winning gets its own independent checker
interface WinningStrategy {
    boolean checkWin(Board board, int row, int col, Symbol symbol);
}

class RowWinStrategy implements WinningStrategy {
    @Override
    public boolean checkWin(Board board, int row, int col, Symbol symbol) {
        for (int c = 0; c < board.getSize(); c++) {
            if (board.getCell(row, c) != symbol) return false;
        }
        return true;
    }
}

class ColumnWinStrategy implements WinningStrategy {
    @Override
    public boolean checkWin(Board board, int row, int col, Symbol symbol) {
        for (int r = 0; r < board.getSize(); r++) {
            if (board.getCell(r, col) != symbol) return false;
        }
        return true;
    }
}

class DiagonalWinStrategy implements WinningStrategy {
    @Override
    public boolean checkWin(Board board, int row, int col, Symbol symbol) {
        int size = board.getSize();
        boolean onMainDiagonal = (row == col);
        boolean onAntiDiagonal = (row + col == size-1);

        if (!onMainDiagonal && !onAntiDiagonal) return false;

        boolean mainWin = onMainDiagonal;
        if (onMainDiagonal) {
            for (int i = 0; i < size; i++) {
                if (board.getCell(i, i) != symbol) { mainWin = false; break; }
            }
        }

        boolean antiWin = onAntiDiagonal;
        if (onAntiDiagonal) {
            for (int i = 0; i < size; i++) {
                if (board.getCell(i, size-1-i) != symbol) { antiWin = false; break; }
            }
        }

        return mainWin || antiWin;
    }
}

// Plain data holder: a player's name and symbol never change once created
