    public void onGameWon(Player player) {
        System.out.println(player.getName() + " wins!");
    }

    @Override
    public void onGameDraw() {
        System.out.println("Game ended in a draw");
    }
}

// Orchestrates the whole game
class TicTacToeGame {
    private Board board;
    private java.util.List<Player> players;
    private int currentPlayerIndex;
    private java.util.List<WinningStrategy> winningStrategies;
    private java.util.List<GameListener> listeners = new ArrayList<>();
    private boolean gameOver;

    TicTacToeGame(int boardSize, java.util.List<Player> players) {
        this.board = new Board(boardSize);
        this.players = players;
        this.currentPlayerIndex = 0;
        this.gameOver = false;

        winningStrategies = new ArrayList<>();
        winningStrategies.add(new RowWinStrategy());
        winningStrategies.add(new ColumnWinStrategy());
        winningStrategies.add(new DiagonalWinStrategy());
    }

    void addListener(GameListener listener) {
        listeners.add(listener);
    }

    boolean makeMove(int row, int col) {
        if (gameOver) {
            return false;
        }

        Player currentPlayer = players.get(currentPlayerIndex);

        if (!board.placeMark(row, col, currentPlayer.getSymbol())) {
            return false;
        }

        for (GameListener listener : listeners) {
            listener.onMoveMade(currentPlayer, row, col);
        }

        for (WinningStrategy strategy : winningStrategies) {
            if (strategy.checkWin(board, row, col, currentPlayer.getSymbol())) {
                gameOver = true;
                for (GameListener listener : listeners) {
                    listener.onGameWon(currentPlayer);
                }
                return true;
            }
        }

        if (board.isFull()) {
            gameOver = true;
            for (GameListener listener : listeners) {
                listener.onGameDraw();
            }
            return true;
        }

        currentPlayerIndex = (currentPlayerIndex + 1) % players.size();
        return false;
    }
}

